import pytest

import reassemble


def test_sv5cd01_negative():
    c = lambda m, s, t, d: {'msg_id': m, 'seq': s, 'total': t, 'data': d}
    r = reassemble.reassemble([c('a', 0, 3, 'x'), c('a', 0, 3, 'y'), c('a', 2, 3, 'z')])
    assert r['a'] == {'status': 'conflict', 'text': None, 'missing': [1], 'conflict_seq': [0]}
    for bad in ([c('a', 0, 2, 'x'), c('a', 1, 3, 'y')], [c('a', 2, 2, 'x')], [c('a', -1, 2, 'x')], [c('a', '0', 2, 'x')]):
        with pytest.raises(ValueError):
            reassemble.reassemble(bad)

import pytest

import reassemble


def test_sv5cd01_boundary():
    c = lambda m, s, t, d: {'msg_id': m, 'seq': s, 'total': t, 'data': d}
    r = reassemble.reassemble([c('a', 3, 5, 'd'), c('a', 0, 5, 'a'), c('a', 0, 5, 'a')])
    assert r['a'] == {'status': 'incomplete', 'text': None, 'missing': [1, 2, 4]}
    assert reassemble.reassemble([c('s', 0, 1, '')]) == {'s': {'status': 'complete', 'text': '', 'missing': []}}
    assert reassemble.reassemble([]) == {}
